import{_ as r,l,o as e,c as s,v as i,p as c,x as o,d as n,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"NUMA 内存策略","description":"","frontmatter":{"title":"NUMA 内存策略","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/numa-mempolicy.md","filePath":"cs/numa-mempolicy.md","lastUpdated":1789023840000}'),d={name:"cs/numa-mempolicy.md"};function u(A,a,h,_,E,f){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="numa-内存策略" tabindex="-1">NUMA 内存策略 <a class="header-anchor" href="#numa-内存策略" aria-label="Permalink to &quot;NUMA 内存策略&quot;">​</a></h1><div class="epigraph"><p>mempolicy 决定缺页从哪个节点取框：本地、绑定、交错或首选，使带宽与延迟跟得上线程所在的 CPU。</p><footer>—— 据 Linux numa(7)；Lameter 对 Linux NUMA 的论述；McKusick 对 UMA/NUMA 的背景</footer></div><p><a href="/cs/zswap">上一课</a>留下的缺口接到本课。 <a href="/cs/page-migration-compaction">迁移</a> 已能搬家。默认 first-touch 本地。多线程与文件页会打破「本地」。缺口是 <strong>NUMA 策略</strong>：<code>mbind</code>/<code>set_mempolicy</code>，不是主板拓扑百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨节点 load 延迟高、带宽走互联。策略：MPOL_BIND 失败则 OOM 或回退（MPOL_F_STRICT）；INTERLEAVE 打散带宽；PREFERRED 尽力。缺口：文件页共享——以谁的策略为准；自动 NUMA balancing 用缺页统计迁页迁任务；与 <a href="/cs/thp">THP</a> 大页跨节点更贵。本课不把每代 AMD/Intel 互联名当课纲。</p><p><span class="marginnote">numactl 是用户接口。内核 per-vma policy 覆盖进程默认。设备 DMA 有自己的节点约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页：查 vma policy → 选 nid → 在该 zone 分配，失败则回退列表。对照 <a href="/cs/rss-multiqueue">RSS</a>：一个散包到 CPU，一个散页到节点。对照 <a href="/cs/cgroups">cgroup</a>：cpuset 可限制节点集合，与 mempolicy 求交。</p>',8)),(e(),c(p,null,{default:o(()=>[m(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20POL%5B%22vma%2F%E8%BF%9B%E7%A8%8B%20mempolicy%22%5D%0A%20%20POL%20--%3E%20NID%5B%22%E7%9B%AE%E6%A0%87%E8%8A%82%E7%82%B9%22%5D%0A%20%20NID%20--%3E%20ALLOC%5B%22%E8%AF%A5%E8%8A%82%E7%82%B9%20buddy%22%5D%0A%20%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20FB%5B%22%E5%9B%9E%E9%80%80%E6%88%96%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>策略把 NUMA 从「内核猜」变成应用可声明的放置。错误的 bind 会 OOM 而邻节点空闲。不要写成量化共址交易。与 <a href="/cs/tmpfs">tmpfs</a>：shmem 页也走 policy。</p><p>自动平衡是启发式，可能与显式策略打架，生产上要选一边。</p><p>实现上：MPOL_BIND 在节点内存满时失败，任务可能 OOM 而邻节点空闲。自动 NUMA balancing 用探测缺页迁任务或页，和显式 mbind 冲突时要关一边。文件页的放置常跟第一次读的节点。 读法上只引用<a href="/cs/zswap">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>NUMA 内存策略</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CXL 内存分层的全部 demote。不保证实时优先级与 NUMA 回退的组合。下一课组级内存上限：memcg。</p><p>版本字段会变，课序钉的是机制对象「NUMA 内存策略」，不是某一主线内核的结构体名。 后课默认：缺页可按节点策略取框。cgroup 如何限制一组进程的内存，下一课 memcg。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mempolicy 选节点：绑定、交错、首选。</li><li>与 cpuset、自动平衡交互。</li><li>memcg 是下一课。</li><li>出处：Linux <code>numa(7)</code>；Lameter；Gorman。</li></ul>',11))])}const N=r(d,[["render",u]]);export{B as __pageData,N as default};
